    msp = doc.modelspace()
    for e in msp:
        layer = e.dxf.layer
        if layer.startswith('E-RTE-'):
            c_name = layer[len('E-RTE-'):]
            length = 0.0
            if e.dxftype() == 'LINE':
                p1 = e.dxf.start
                p2 = e.dxf.end
                length = math.hypot(p2[0]-p1[0], p2[1]-p1[1])
            elif e.dxftype() == 'LWPOLYLINE':
                pts = e.get_points('xy')
                for i in range(len(pts)-1):
                    length += math.hypot(pts[i+1][0]-pts[i][0], pts[i+1][1]-pts[i][1])
            elif e.dxftype() == 'POLYLINE':
                pts = [v.dxf.location for v in e.vertices]
                for i in range(len(pts)-1):
                    length += math.hypot(pts[i+1][0]-pts[i][0], pts[i+1][1]-pts[i][1])
            else:
                print(f'Other entity {e.dxftype()} on {layer}')
            circuit_lengths[c_name] = circuit_lengths.get(c_name, 0.0) + length

for c in sorted(circuit_lengths.keys()):
    print(f'{c}: plan length = {circuit_lengths[c]:.2f} ft')
